dur = {"OEM 요구사항": 3, "마이크·ECNR 튜닝": 6, "ASR 엔진 연동": 4,
       "에이전트 서버": 5, "차량 제어 API": 4, "통합 빌드": 1, "실차 검증": 3}
dep = {"마이크·ECNR 튜닝": ["OEM 요구사항"], "ASR 엔진 연동": ["OEM 요구사항"],
       "에이전트 서버": ["OEM 요구사항"], "차량 제어 API": ["OEM 요구사항"],
       "통합 빌드": ["마이크·ECNR 튜닝", "ASR 엔진 연동", "에이전트 서버", "차량 제어 API"],
       "실차 검증": ["통합 빌드"]}
end, via = {}, {}
def f(t):
    if t not in end:
        best = max(dep.get(t, []), key=f, default=None)
        via[t] = best
        end[t] = (f(best) if best else 0) + dur[t]
    return end[t]
t, path = "실차 검증", []
total = f(t)
while t:
    path.append(t); t = via[t]
print(f"임계 경로 {total}주: " + " → ".join(reversed(path)))
